using Archy.Features.Placement.AdviseSplitOrAppend;
namespace Archy.Features.Advisories.ComposeUnifiedAdvisories;
/// <summary>Bounded recommendation composition; deterministic blocking violations remain a separate, non-advisory result channel.</summary>
public sealed class UnifiedAdvisoryComposer:IUnifiedAdvisoryComposer { public UnifiedAdvisoryResult Compose(UnifiedAdvisoryInput input){ArgumentNullException.ThrowIfNull(input);ArgumentNullException.ThrowIfNull(input.IntroducedBlockingViolationIds);if(input.IntroducedBlockingViolationIds.Any(string.IsNullOrWhiteSpace))throw new ArgumentException("Violation identities must be non-empty.",nameof(input));var items=new List<AdvisoryItem>();if(input.DuplicateFeedback is not null)items.Add(new("duplicate",input.DuplicateFeedback.SuppressRepeatedFinding?0d:.5d,input.DuplicateFeedback.SuppressRepeatedFinding?"An exact-pair ignore decision exists.":"Review duplicate evidence if independently corroborated.",input.DuplicateFeedback.DecisionIds,input.DuplicateFeedback.SuppressRepeatedFinding));if(input.Placement is not null){var best=input.Placement.Candidates.Count==0?null:input.Placement.Candidates[0];items.Add(new("placement",best?.WeightedOverlap??0d,input.Placement.Reason,best is null?[]:[best.ClusterKey],input.Placement.IsAbstention));}if(input.SplitAppend is not null)items.Add(new("split_append",input.SplitAppend.Kind==SplitAppendAdviceKind.Abstain?0d:.5d,input.SplitAppend.Reason,input.SplitAppend.SuggestedFileName is null?[]:[input.SplitAppend.SuggestedFileName],input.SplitAppend.Kind==SplitAppendAdviceKind.Abstain));return new([..input.IntroducedBlockingViolationIds.Distinct(StringComparer.Ordinal).OrderBy(x=>x,StringComparer.Ordinal)],[..items.OrderByDescending(x=>x.Confidence).ThenBy(x=>x.Kind,StringComparer.Ordinal).Take(10)]);}}
